'use strict';
// A bounded stored ZIP: no runtime package or remote service is needed.
const zipCRC=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0;}return bytes=>{let c=0xffffffff;for(const b of bytes)c=t[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;};})();
function zipFiles(files){const chunks=[],central=[];let offset=0,centralSize=0;const enc=new TextEncoder();for(const [name,bytes]of files){const filename=enc.encode(name),crc=zipCRC(bytes),head=new Uint8Array(30+filename.length),h=new DataView(head.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint16(12,0x21,true);h.setUint32(14,crc,true);h.setUint32(18,bytes.length,true);h.setUint32(22,bytes.length,true);h.setUint16(26,filename.length,true);head.set(filename,30);const dir=new Uint8Array(46+filename.length),d=new DataView(dir.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint16(14,0x21,true);d.setUint32(16,crc,true);d.setUint32(20,bytes.length,true);d.setUint32(24,bytes.length,true);d.setUint16(28,filename.length,true);d.setUint32(42,offset,true);dir.set(filename,46);chunks.push(head,bytes);central.push(dir);offset+=head.length+bytes.length;centralSize+=dir.length;}const end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,centralSize,true);e.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
$('campaign-export').onclick=()=>serial(async()=>{
 if(drafts.size){notice('Apply or discard your form edits before exporting the campaign.',true);return;}
 const variants=state.studio?.variants||[];if(!variants.length){notice('Start a campaign or save a layout first.');return;}
 if(variants.reduce((n,v)=>n+v.pages,0)>100)throw Error('Campaign bundles support up to 100 pages. Export larger layouts individually.');
 const revision=state.revision,doc=state.document_id,files=[],manifest={version:1,studio_version:state.version,title:state.title,revision,layouts:[]};let total=0;
 const read=async(path)=>{const r=await api(path,{headers:{'X-Canvas-Document':doc,'X-Canvas-Revision':String(revision)}});if(Number(r.headers.get('X-Canvas-Revision'))!==revision)throw Error('Campaign changed during export; review and retry.');const data=new Uint8Array(await r.arrayBuffer());total+=data.length;if(total>128*1024*1024)throw Error('Bundle exceeds 128 MiB. Export layouts individually.');return data;};
 files.push(['campaign.canvas',await read('/api/download.canvas')]);
 for(let i=0;i<variants.length;i++){const v=variants[i],slug=String(i+1).padStart(2,'0')+'-'+v.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),q='variant='+encodeURIComponent(v.name);notice('Preparing '+v.name+'…');files.push([slug+'/'+slug+'.pdf',await read('/api/download.pdf?'+q)]);for(let n=0;n<v.pages;n++)files.push([`${slug}/page-${String(n+1).padStart(3,'0')}.png`,await read(`/api/download.png?${q}&page=${n}&dpi=96`)]);manifest.layouts.push({name:v.name,width:v.width,height:v.height,pages:v.pages,png_dpi:96,folder:slug});}
 files.push(['manifest.json',new TextEncoder().encode(JSON.stringify(manifest,null,2))]);const url=URL.createObjectURL(zipFiles(files)),a=elem('a',{href:url,download:'campaign.zip'});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);notice('Campaign bundle downloaded: editable project, PDFs, PNGs and manifest.');
});
